import pandas as pd

def second_best(attempts):
    """Return each student's second-highest attempt (duplicates count)."""
    ranked = attempts.sort_values(
        ["student", "score"], ascending=[True, False]
    )
    keep = ranked.groupby("student").cumcount() == 1
    return ranked.loc[keep, ["student", "score"]].reset_index(drop=True)

import pandas as pd

def cap_outliers(readings):
    """Cap minutes values above the 90th percentile at that percentile."""
    cap = readings["minutes"].quantile(0.9)
    return readings["minutes"].clip(upper=cap).round(2)
